(()=>{const form=document.querySelector('.quote-flow');if(!form)return;const es=document.documentElement.lang==='es',tr=(a,b)=>es?b:a;const panels=[...form.querySelectorAll('.quote-step')],progress=[...form.querySelectorAll('.quote-progress li')],next=form.querySelector('.quote-next'),back=form.querySelector('.quote-back');let step=0;const service=()=>form.querySelector('[name=service]:checked').value;const labels=es?{service:'Servicio',timing:'Cuándo',running:'Estado',title:'Título',use:'Uso',location:'Ubicación',vehicle:'Vehículo',destination:'Destino',year:'Año',start:'Inicio',end:'Regreso',name:'Nombre',phone:'Teléfono',details:'Detalles'}:{service:'Service',timing:'When',running:'Condition',title:'Title',use:'Use',location:'Location',vehicle:'Vehicle',destination:'Destination',year:'Year',start:'Start',end:'Return',name:'Name',phone:'Phone',details:'Details'};
function entries(){return [...new FormData(form)].filter(([,v])=>v.trim()).map(([k,v])=>[labels[k]||k,k==='service'?form.querySelector('[name=service]:checked+span strong').textContent:v])}
function message(){return 'MCS 86 Towing\n'+entries().map(([k,v])=>`${k}: ${v}`).join('\n')}
function updateFields(){form.querySelectorAll('[data-quote-for]').forEach(group=>{const hide=!group.dataset.quoteFor.split(' ').includes(service());group.hidden=hide;group.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=hide)});const start=form.elements.start,end=form.elements.end;if(start?.value)end.min=start.value;else end.removeAttribute('min')}
function show(focus=true){updateFields();panels.forEach((p,i)=>p.hidden=i!==step);progress.forEach((p,i)=>{p.classList.toggle('current',i===step);p.classList.toggle('complete',i<step);if(i===step)p.setAttribute('aria-current','step');else p.removeAttribute('aria-current')});form.querySelector('.quote-count').textContent=tr(`Step ${step+1} of 4`,`Paso ${step+1} de 4`);back.hidden=step===0;next.hidden=step===3;if(step===3){const review=form.querySelector('.quote-review');review.replaceChildren();for(const [label,value]of entries()){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;review.append(dt,dd)}}if(focus){panels[step].querySelector('h3').focus({preventScroll:true});form.scrollIntoView({block:'start',behavior:'auto'})}}
const desired=new URLSearchParams(location.search).get('service');if(desired){[...form.querySelectorAll('[name=service]')].find(r=>r.value===desired)?.click()}
form.classList.add('guided');form.querySelector('.quote-nav').hidden=false;form.noValidate=true;show(false);form.addEventListener('change',updateFields);next.addEventListener('click',()=>{for(const el of panels[step].querySelectorAll('input,select,textarea')){if(!el.disabled&&!el.reportValidity())return}step=Math.min(3,step+1);show()});back.addEventListener('click',()=>{step=Math.max(0,step-1);show()});form.addEventListener('submit',event=>{event.preventDefault();if(step!==3){next.click();return}const msg=message(),box=form.querySelector('.quote-message');box.hidden=false;box.querySelector('textarea').value=msg;form.querySelector('.quote-status').textContent=tr('Message prepared. Nothing has been sent. Send it from your messaging app.','Mensaje preparado. No se ha enviado nada. Envíalo desde tu aplicación de mensajes.');location.href='sms:+19098276022?body='+encodeURIComponent(msg)});
})();

